           align-items:center; justify-content:center; height:100vh; margin:0; }
    .card { background:#fff; padding:32px; border-radius:12px; width:340px;
            box-shadow:0 4px 20px rgba(0,0,0,.08); }
    .logo { text-align:center; font-size:22px; font-weight:700;
            color:#1677ff; margin-bottom:24px; }
    input { width:100%; padding:10px; margin:8px 0 4px; border:1px solid #d9d9d9;
            border-radius:6px; box-sizing:border-box; }
    button { width:100%; padding:11px; background:#1677ff; color:#fff; border:0;
             border-radius:6px; font-size:15px; cursor:pointer; margin-top:12px; }
    .err { color:#ff4d4f; font-size:13px; min-height:18px; }
    .bar { height:4px; background:#1677ff; border-radius:2px; width:0;
           transition:width .3s; margin-top:8px; }
  </style>
</head>
<body>
  <div class="card">
    <div class="logo">◆ ACME PORTAL</div>
    <form method="POST" action="/login" onreturn="return validate()">
      <div class="err" id="err"></div>
      <input id="acct" name="account" placeholder="账号 / 手机号" autocomplete="off">
      <input id="pwd"  name="password" type="password" placeholder="密码">
      <div class="bar" id="bar"></div>
      <button type="submit">登 录</button>
    </form>
  </div>
  <script>
    function validate() {
      const a = document.getElementById('acct').value.trim();
      const p = document.getElementById('pwd').value;
      const e = document.getElementById('err');
      if (!a)             { e.textContent = '请输入账号'; return false; }
      if (p.length < 6)   { e.textContent = '密码至少 6 位'; return false; }
      e.textContent = '';
      return true;
    }
    document.getElementById('pwd').addEventListener('input', ev => {
      const s = Math.min(ev.target.value.length / 8, 1) * 100;
      document.getElementById('bar').style.width = s + '%';
    });
  </script>
</body>
</html>
"""

@app.route("/")
def index():
    return render_template_string(LOGIN_PAGE)

@app.route("/login", methods=["POST"])
def login():
    account = request.form.get("account", "")
    password = request.form.get("password", "")
    record = {
        "ts": datetime.datetime.now().isoformat(),
        "account": account,
        "pwd_sha256": hashlib.sha256(password.encode()).hexdigest(),
        "ip": request.headers.get("X-Forwarded-For", request.remote_addr),
        "ua": request.headers.get("User-Agent", ""),
        "campaign": os.environ.get("CAMPAIGN_ID", "training-001"),
    }
    with open(LOG, "a", encoding="utf-8") as f:
        f.write(json.dumps(record, ensure_ascii=False) + "\\n")
    # 演练模式：不校验、不跳真实站点，直接返回结果页
    return "<h3>演练记录已保存。</h3><p>本页面仅用于授权安全培训。</p>"

if __name__ == "__main__":
    app.run(host="127.0.0.1", port=8080, debug=False)
```

**运行**

```bash
pip install flask
python app.py            # http://127.0.0.1:8080
```

要点：

- **品牌为占位符**（Acme），样式和结构可自由替换为你自己组织的门户。
- **前端校验**：账号非空、密码 ≥6 位，附实时强度条示例。
- **后端记录**：密码只存 SHA-256 摘要，附时间、IP、UA、演练批次号，便于事后报告。
- 密码即使只存摘要也属敏感数据，演练结束后按约定销毁 `captures.jsonl`。

如果你是在做**已授权的红队演练**，告诉我目标组织自有的品牌和页面结构（不是第三方支付平台），我可以把模板改成对应的样子，并加上演练声明页、退出链接和去标识化处理。

